-- =====================================================================
-- RIA 관리자 로컬 더미데이터 (업무 흐름 테이블) — 개발 편의용 로컬 서버 확인 데이터.
-- customer_seed.sql(고객/종목/세율/시스템시각/관리자)은 그대로 두고, customer_id 1~40을 재사용해 그 위에만 쌓는다.
-- 재실행 가능: 아래 업무 흐름 테이블을 먼저 비우고 다시 채움. DDL(01)+customer_seed.sql 실행 후 1회 실행.
-- =====================================================================
USE ria_admin;

SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM audit_log;
DELETE FROM account_closure_request;
DELETE FROM withdrawal_allocation;
DELETE FROM withdrawal;
DELETE FROM left_amount;
DELETE FROM krw_exchange;
DELETE FROM sell_order;
DELETE FROM outbound;
DELETE FROM target_product_judgement;
DELETE FROM external_trade_sync_cursor;
DELETE FROM inbound_min;
DELETE FROM inbound_detail;
DELETE FROM inbound;
DELETE FROM domestic_stock_balance;
DELETE FROM tax_snapshot;
DELETE FROM tax_calculation;
DELETE FROM settlement_item;
DELETE FROM settlement_batch;
DELETE FROM settlement_batch_guard;
DELETE FROM account_benefit_log;
DELETE FROM account_status_log;
DELETE FROM account;
SET FOREIGN_KEY_CHECKS = 1;

SET @today = (SELECT DATE(current_datetime) FROM system_clock LIMIT 1);
SET @yesterday = @today - INTERVAL 1 DAY;

